fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let rows = y.len();
    let cols = x.len();

    let mut x_grid: Vec<Vec<f32>> = Vec::with_capacity(rows);
    let mut y_grid: Vec<Vec<f32>> = Vec::with_capacity(rows);

    for &y_val in &y {
        // Row for x_grid is always x repeated (same across all rows)
        x_grid.push(x.clone());

        // Row for y_grid is y_val repeated across all columns
        let mut y_row = Vec::with_capacity(cols);
        y_row.resize(cols, y_val);
        y_grid.push(y_row);
    }

    (x_grid, y_grid)
}